// Entry: tab switching + lazy dynamic import of each editor (code-split)
import './main.css';

const mounted = { word: false, excel: false, slides: false };
const instances = { word: null, excel: null, slides: null };
const loadStart = { word: 0, excel: 0, slides: 0 };

function setStatus(pane, msg, color) {
  const head = pane.querySelector('.pane-head');
  if (head) head.innerHTML = `<span style="color:${color || 'var(--muted)'}">${msg}</span>`;
}

async function activate(name) {
  document.querySelectorAll('.tab').forEach(t => {
    const sel = t.dataset.tab === name;
    t.setAttribute('aria-selected', sel ? 'true' : 'false');
  });
  document.querySelectorAll('.pane').forEach(p => {
    p.hidden = p.dataset.pane !== name;
  });
  if (mounted[name]) return;

  const pane = document.querySelector(`.pane[data-pane="${name}"]`);
  if (!pane) return;

  // Show loading state
  const t0 = performance.now();
  setStatus(pane, `⏳ 加载 ${name} 模块（首次需下载引擎）...`);
  console.info(`[main] dynamic import ./${name}.js`);

  try {
    const mod = await import(`./${name}.js`);
    const mount = mod[`mount${name[0].toUpperCase() + name.slice(1)}`];
    if (!mount) throw new Error('mount function not found: ' + name);
    const t1 = performance.now();
    loadStart[name] = t1 - t0;
    instances[name] = mount();
    mounted[name] = true;
    const t2 = performance.now();
    setStatus(pane, `✅ 加载完成（下载 ${loadStart[name].toFixed(0)}ms + 挂载 ${(t2-t1).toFixed(0)}ms）`, 'var(--accent)');
    console.info(`[main] mounted ${name} in ${(t2-t0).toFixed(0)}ms`);
  } catch (e) {
    console.error(`[main] failed to mount ${name}`, e);
    pane.innerHTML = `<div style="padding:24px;color:#a00">❌ 挂载失败：${e.message}<br><pre>${(e.stack||'').slice(0,500)}</pre></div>`;
  }
}

document.querySelectorAll('.tab').forEach(t => {
  t.addEventListener('click', () => activate(t.dataset.tab));
});

// Default: Word tab on load
activate('word');

// Expose for console debugging
window.poc = { mounted, instances, activate, loadStart };
